<?php require __DIR__.'/includes/core.php';$u=require_login(['teacher','supervisor','admin','management']);$id=(int)($_GET['id']??0);if($u['role']==='teacher')ensure_teacher_self_evaluations((int)$u['id']);$a=one('SELECT a.*,m.name module_name,m.slug module_slug,m.evaluator_role,m.is_active,c.is_open,c.starts_at,c.ends_at,t.name teacher_name,t.gender,t.classes,t.subjects,t.section_id,s.name session_name,c.term FROM assignments a JOIN modules m ON m.id=a.module_id JOIN evaluation_cycles c ON c.id=a.cycle_id JOIN academic_sessions s ON s.id=c.session_id JOIN users t ON t.id=a.subject_id WHERE a.id=?',[$id]);if(!$a||$a['evaluator_id']!=$u['id']||$a['evaluator_role']!==$u['role']||!$a['is_active']||($a['module_slug']==='personal-evaluation' && ($a['subject_id']!=$u['id']||$u['role']!=='teacher'))){http_response_code(403);exit('Evaluation assignment unavailable.');}if($a['status']==='submitted')exit('This evaluation was submitted successfully and is locked.');$today=date('Y-m-d');$open=$a['is_open']&&(!$a['starts_at']||$today>=$a['starts_at'])&&(!$a['ends_at']||$today<=$a['ends_at']);if(!$open)exit('This evaluation cycle is closed.');$sections=all('SELECT * FROM template_sections WHERE module_id=? ORDER BY sort_order,id',[$a['module_id']]);$opts=all('SELECT * FROM rating_options WHERE module_id=? ORDER BY rating',[$a['module_id']]);$existing=[];foreach(all('SELECT criterion_id,rating FROM responses WHERE assignment_id=?',[$id]) as $r)$existing[$r['criterion_id']]=$r['rating'];$comment=one('SELECT * FROM evaluation_comments WHERE assignment_id=?',[$id])??[];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$isSubmit=($_POST['mode']??'draft')==='submit';$valid=[];foreach($sections as $s){foreach(all('SELECT id FROM criteria WHERE section_id=?',[$s['id']]) as $c){$key='c'.$c['id'];if(!isset($_POST[$key])||$_POST[$key]===''){if($isSubmit)$error='Please rate every indicator before submitting.';continue;}$v=(int)$_POST[$key];if(!in_array($v,array_column($opts,'rating'))) {$error='Invalid rating selected.';continue;}$valid[$c['id']]=$v;}}if(!$error){try{db()->beginTransaction();$lock=one('SELECT status FROM assignments WHERE id=? FOR UPDATE',[$id]);if($lock['status']==='submitted')throw new Exception('Already submitted.');foreach($valid as $cid=>$rating)sql('INSERT INTO responses(assignment_id,criterion_id,rating) VALUES (?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating)',[$id,$cid,$rating]);sql('INSERT INTO evaluation_comments(assignment_id,strengths,improvements,impression,remarks) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE strengths=VALUES(strengths),improvements=VALUES(improvements),impression=VALUES(impression),remarks=VALUES(remarks)',[$id,trim($_POST['strengths']??''),trim($_POST['improvements']??''),trim($_POST['impression']??''),trim($_POST['remarks']??'')]);sql('UPDATE assignments SET observation_date=?,subject_name=?,class_name=?,period_name=?,status=?,submitted_at=IF(?="submitted",NOW(),NULL) WHERE id=?',[$_POST['observation_date']?:null,trim($_POST['subject_name']??''),trim($_POST['class_name']??''),trim($_POST['period_name']??''),$isSubmit?'submitted':'draft',$isSubmit?'submitted':'draft',$id]);db()->commit();audit($isSubmit?'evaluation_submitted':'evaluation_draft_saved',(string)$id);flash($isSubmit?'Evaluation submitted successfully.':'Draft saved.');go(dashboard_path($u['role']));}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error='Could not save evaluation. Please retry.';}}}$sectionsCount=0;ob_start();if($error)echo '<div class="alert error">'.h($error).'</div>';?><div class="card"><h2><?=h($a['module_name'])?> — <?=h($a['teacher_name'])?></h2><p><strong>Session:</strong> <?=h($a['session_name'])?> &nbsp; <strong>Term:</strong> <?=h($a['term'])?></p><p class="muted">Your ratings are confidential and will not be shown on submission.</p></div><form method="post"><?=token()?><div class="card"><div class="formgrid"><div><label>Evaluation date</label><input type="date" name="observation_date" value="<?=h($_POST['observation_date']??$a['observation_date']??date('Y-m-d'))?>"></div><div><label>Subject</label><input name="subject_name" value="<?=h($_POST['subject_name']??$a['subject_name']??$a['subjects'])?>"></div><div><label>Class</label><input name="class_name" value="<?=h($_POST['class_name']??$a['class_name']??$a['classes'])?>"></div><div><label>Period</label><input name="period_name" value="<?=h($_POST['period_name']??$a['period_name'])?>"></div></div></div><?php foreach($sections as $s){?><div class="card"><h2><?=h($s['title'])?></h2><?php foreach(all('SELECT * FROM criteria WHERE section_id=? ORDER BY sort_order,id',[$s['id']]) as $c){$sectionsCount++;$descs=[];foreach(all('SELECT rating,description FROM rating_descriptions WHERE criterion_id=?',[$c['id']]) as $d)$descs[$d['rating']]=$d['description'];?><div style="padding:12px 0;border-bottom:1px solid #ddd"><strong><?=$sectionsCount?>. <?=h($c['title'])?></strong><div class="choices"><?php foreach($opts as $o){$selected=$_POST['c'.$c['id']]??$existing[$c['id']]??'';?><label><input type="radio" name="c<?=$c['id']?>" value="<?=h($o['rating'])?>" <?=((string)$selected===(string)$o['rating'])?'checked':''?>> <b><?=h($o['rating'])?> — <?=h($o['label'])?></b><?php if(!empty($descs[$o['rating']]))echo '<br><span class="small">'.h($descs[$o['rating']]).'</span>';?></label><?php }?></div></div><?php }?></div><?php }?><div class="card"><label><?=($a['module_slug']==='personal-evaluation')?'My three greatest teaching strengths this term':'Strengths observed'?></label><textarea name="strengths" rows="3"><?=h($_POST['strengths']??$comment['strengths']??'')?></textarea><label><?=($a['module_slug']==='personal-evaluation')?'My challenges and areas for improvement':'Suggestions for improvement'?></label><textarea name="improvements" rows="3"><?=h($_POST['improvements']??$comment['improvements']??'')?></textarea><label><?=($a['module_slug']==='personal-evaluation')?'Evidence of learner progress and my achievements':'Overall impression of teaching effectiveness'?></label><textarea name="impression" rows="3"><?=h($_POST['impression']??$comment['impression']??'')?></textarea><label><?=($a['module_slug']==='personal-evaluation')?'My professional development goals and support needed':'Additional remarks'?></label><textarea name="remarks" rows="3"><?=h($_POST['remarks']??$comment['remarks']??'')?></textarea><div class="actions"><button name="mode" value="draft" formnovalidate>Save draft</button><button name="mode" value="submit" onclick="return confirm('Submit this evaluation permanently? Scores will remain confidential.')">Submit evaluation</button></div></div></form><?php layout($a['module_name'].' form',ob_get_clean());